cat > src/queue.rs <<'EOF'
use std::collections::{BTreeMap, HashMap, HashSet};

use serde::Serialize;

use crate::types::{MessageId, ReceiptHandle, Seconds};

pub const MAX_MESSAGES: usize = 100_000;
const DEDUP_WINDOW: Seconds = Seconds(300);

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Attributes {
    pub visibility_timeout: Seconds,
    pub delay: Seconds,
    pub retention: Seconds,
    pub fifo: bool,
    pub content_based_dedup: bool,
    pub dead_letter: Option<DeadLetter>,
}

impl Default for Attributes {
    fn default() -> Self {
        Self {
            visibility_timeout: Seconds(30),
            delay: Seconds(0),
            retention: Seconds(345_600),
            fifo: false,
            content_based_dedup: false,
            dead_letter: None,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    Delayed,
    InFlight,
    Visible,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Counts {
    #[serde(rename = "Visible")]
    pub visible: usize,
    #[serde(rename = "InFlight")]
    pub in_flight: usize,
    #[serde(rename = "Delayed")]
    pub delayed: usize,
}

#[derive(Debug)]
struct Placement {
    group: String,
    sequence: u64,
}

#[derive(Debug)]
pub struct Message {
    id: MessageId,
    body: String,
    sent_at: Seconds,
    delayed_until: Seconds,
    in_flight_until: Option<Seconds>,
    receive_count: u32,
    first_received_at: Option<Seconds>,
    /// Latest handle issued for this message; older handles are expired.
    receipt: Option<ReceiptHandle>,
    placement: Option<Placement>,
}

impl Message {
    fn state(&self, now: Seconds) -> State {
        if now < self.delayed_until {
            State::Delayed
        } else if self.in_flight_until.is_some_and(|until| now < until) {
            State::InFlight
        } else {
            State::Visible
        }
    }

    fn group(&self) -> Option<&str> {
        self.placement.as_ref().map(|p| p.group.as_str())
    }
}

/// One delivered message as the `ReceiveMessage` response lists it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "PascalCase")]
pub struct Delivery {
    pub message_id: MessageId,
    pub receipt_handle: ReceiptHandle,
    pub body: String,
    pub receive_count: u32,
    pub sent_at: Seconds,
    pub first_received_at: Seconds,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub group_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub sequence_number: Option<u64>,
}

/// What a FIFO send adds to a plain send.
pub struct FifoSend<'a> {
    pub group: &'a str,
    pub dedup_id: &'a str,
}

pub struct Receipt {
    pub delivered: Vec<Delivery>,
    /// Messages removed from this queue that the caller must hand to the dead-letter queue.
    pub dead: Vec<Message>,
}

#[derive(Debug)]
struct Accepted {
    at: Seconds,
    id: MessageId,
    sequence: u64,
}

#[derive(Debug)]
pub struct Queue {
    pub attributes: Attributes,
    /// Keyed by arrival number, which is never reused, so iteration is arrival order.
    messages: BTreeMap<u64, Message>,
    next_arrival: u64,
    next_sequence: u64,
    /// Latest handle of each message that has been delivered, to its arrival number.
    handles: HashMap<ReceiptHandle, u64>,
    /// Outlives the messages: a deduplication id stays taken after its message is gone.
    dedup: HashMap<String, Accepted>,
}

impl Queue {
    pub fn new(attributes: Attributes) -> Self {
        Self {
            attributes,
            messages: BTreeMap::new(),
            next_arrival: 0,
            next_sequence: 1,
            handles: HashMap::new(),
            dedup: HashMap::new(),
        }
    }

    pub fn is_full(&self) -> bool {
        self.messages.len() >= MAX_MESSAGES
    }

    pub fn counts(&self, now: Seconds) -> Counts {
        let mut counts = Counts { visible: 0, in_flight: 0, delayed: 0 };
        for message in self.messages.values() {
            match message.state(now) {
                State::Visible => counts.visible += 1,
                State::InFlight => counts.in_flight += 1,
                State::Delayed => counts.delayed += 1,
            }
        }
        counts
    }

    /// The original message of a send whose deduplication id was accepted within the window.
    pub fn duplicate_of(&self, now: Seconds, dedup_id: &str) -> Option<(MessageId, u64)> {
        let accepted = self.dedup.get(dedup_id)?;
        (now - accepted.at < DEDUP_WINDOW).then_some((accepted.id, accepted.sequence))
    }

    /// Adds a message; the caller has checked the limit and duplicates. Returns the sequence
    /// number on a FIFO queue.
    pub fn accept(
        &mut self,
        now: Seconds,
        id: MessageId,
        body: &str,
        delay: Option<Seconds>,
        fifo: Option<FifoSend<'_>>,
    ) -> Option<u64> {
        let delay = delay.unwrap_or(self.attributes.delay);
        let placement = fifo.map(|send| {
            let sequence = self.next_sequence;
            self.next_sequence += 1;
            self.dedup.insert(send.dedup_id.to_owned(), Accepted { at: now, id, sequence });
            Placement { group: send.group.to_owned(), sequence }
        });
        let sequence = placement.as_ref().map(|p| p.sequence);
        self.push(Message {
            id,
            body: body.to_owned(),
            sent_at: now,
            delayed_until: now + delay,
            in_flight_until: None,
            receive_count: 0,
            first_received_at: None,
            receipt: None,
            placement,
        });
        sequence
    }

    /// Takes a message moved from another queue's dead-letter handling. The move ignores the
    /// message limit and deduplication.
    pub fn accept_dead(&mut self, now: Seconds, mut message: Message) {
        message.receive_count = 0;
        message.first_received_at = None;
        message.delayed_until = now;
        message.in_flight_until = None;
        message.receipt = None;
        if self.attributes.fifo {
            let sequence = self.next_sequence;
            self.next_sequence += 1;
            if let Some(placement) = &mut message.placement {
                placement.sequence = sequence;
            }
        }
        if now < message.sent_at + self.attributes.retention {
            self.push(message);
        }
    }

    fn push(&mut self, message: Message) {
        self.messages.insert(self.next_arrival, message);
        self.next_arrival += 1;
    }

    fn remove(&mut self, arrival: u64) -> Option<Message> {
        let message = self.messages.remove(&arrival)?;
        if let Some(handle) = message.receipt {
            self.handles.remove(&handle);
        }
        Some(message)
    }

    /// Removes every message whose retention has run out.
    pub fn expire(&mut self, now: Seconds) {
        let retention = self.attributes.retention;
        self.messages.retain(|_, m| now < m.sent_at + retention);
        let messages = &self.messages;
        self.handles.retain(|_, arrival| messages.contains_key(arrival));
        self.dedup.retain(|_, accepted| now - accepted.at < DEDUP_WINDOW);
    }

    pub fn purge(&mut self) {
        self.messages.clear();
        self.handles.clear();
    }

    pub fn receive(
        &mut self,
        now: Seconds,
        max_messages: usize,
        visibility_timeout: Seconds,
        next_handle: &mut u64,
    ) -> Receipt {
        let mut deliver = Vec::new();
        let mut dead = Vec::new();
        let mut seen_groups: HashSet<&str> = HashSet::new();
        for (&arrival, message) in &self.messages {
            if deliver.len() == max_messages {
                break;
            }
            let group = message.group();
            let eligible = message.state(now) == State::Visible
                && !group.is_some_and(|g| seen_groups.contains(g));
            let moves_to_dead_letter = eligible
                && self
                    .attributes
                    .dead_letter
                    .as_ref()
                    .is_some_and(|dl| message.receive_count >= dl.max_receive_count);
            if let (Some(group), false) = (group, moves_to_dead_letter) {
                seen_groups.insert(group);
            }
            if moves_to_dead_letter {
                dead.push(arrival);
            } else if eligible {
                deliver.push(arrival);
            }
        }

        let dead = dead.into_iter().filter_map(|arrival| self.remove(arrival)).collect();
        let delivered = deliver
            .into_iter()
            .map(|arrival| {
                let handle = ReceiptHandle(*next_handle);
                *next_handle += 1;
                let message = self
                    .messages
                    .get_mut(&arrival)
                    .expect("arrival numbers were taken from this map and nothing was removed since");
                if let Some(old) = message.receipt.replace(handle) {
                    self.handles.remove(&old);
                }
                self.handles.insert(handle, arrival);
                message.receive_count += 1;
                let first_received_at = *message.first_received_at.get_or_insert(now);
                message.in_flight_until = Some(now + visibility_timeout);
                Delivery {
                    message_id: message.id,
                    receipt_handle: handle,
                    body: message.body.clone(),
                    receive_count: message.receive_count,
                    sent_at: message.sent_at,
                    first_received_at,
                    group_id: message.placement.as_ref().map(|p| p.group.clone()),
                    sequence_number: message.placement.as_ref().map(|p| p.sequence),
                }
            })
            .collect();
        Receipt { delivered, dead }
    }

    /// Arrival number of the message that `handle` is the latest handle of, while in flight.
    fn in_flight_arrival(&self, now: Seconds, handle: ReceiptHandle) -> Option<u64> {
        let arrival = *self.handles.get(&handle)?;
        let message = self.messages.get(&arrival)?;
        (message.receipt == Some(handle) && message.state(now) == State::InFlight).then_some(arrival)
    }

    /// Returns false when the handle is not usable.
    pub fn delete_message(&mut self, now: Seconds, handle: ReceiptHandle) -> bool {
        match self.in_flight_arrival(now, handle) {
            Some(arrival) => self.remove(arrival).is_some(),
            None => false,
        }
    }

    /// Returns false when the handle is not usable.
    pub fn change_visibility(&mut self, now: Seconds, handle: ReceiptHandle, timeout: Seconds) -> bool {
        let Some(arrival) = self.in_flight_arrival(now, handle) else {
            return false;
        };
        match self.messages.get_mut(&arrival) {
            Some(message) => {
                message.in_flight_until = Some(now + timeout);
                true
            }
            None => false,
        }
    }
}
EOF
