//! Turns one input line into a typed [`Request`], applying the shape, required-parameter and
//! parameter-value checks in the order the specification gives them.

use serde_json::{Map, Value};

use crate::error::{Code, Error};
use crate::types::Seconds;

/// Attributes as given in a request; `None` means absent.
#[derive(Debug, Default, PartialEq, Eq)]
pub struct AttributeSet {
    pub visibility_timeout: Option<Seconds>,
    pub delay: Option<Seconds>,
    pub retention: Option<Seconds>,
    pub fifo: Option<bool>,
    pub content_based_dedup: Option<bool>,
    pub dead_letter_queue: Option<String>,
    pub max_receive_count: Option<u32>,
}

#[derive(Debug, PartialEq, Eq)]
pub enum Request {
    CreateQueue { name: String, attributes: AttributeSet },
    SetQueueAttributes { name: String, attributes: AttributeSet },
    GetQueueAttributes { name: String },
    ListQueues { prefix: Option<String> },
    DeleteQueue { name: String },
    PurgeQueue { name: String },
    Tick { seconds: Seconds },
    SendMessage {
        name: String,
        body: String,
        delay: Option<Seconds>,
        group_id: Option<String>,
        dedup_id: Option<String>,
    },
    ReceiveMessage { name: String, max_messages: usize, visibility_timeout: Option<Seconds> },
    DeleteMessage { name: String, handle: String },
    ChangeMessageVisibility { name: String, handle: String, visibility_timeout: Seconds },
}

fn invalid(message: String) -> Error {
    Error::new(Code::InvalidParameterValue, message)
}

struct Params(Map<String, Value>);

impl Params {
    /// A `null` member counts as absent.
    fn get(&self, key: &str) -> Option<&Value> {
        self.0.get(key).filter(|v| !v.is_null())
    }

    fn required(&self, key: &str) -> Result<&Value, Error> {
        self.get(key)
            .ok_or_else(|| Error::new(Code::MissingParameter, format!("{key} is required")))
    }

    fn string(&self, key: &str) -> Result<Option<String>, Error> {
        self.get(key).map(|v| string(key, v)).transpose()
    }

    fn int(&self, key: &str, min: i64, max: i64) -> Result<Option<i64>, Error> {
        self.get(key).map(|v| int(key, v, min, max)).transpose()
    }

    fn seconds(&self, key: &str, min: i64, max: i64) -> Result<Option<Seconds>, Error> {
        Ok(self.int(key, min, max)?.map(seconds))
    }
}

fn string(key: &str, value: &Value) -> Result<String, Error> {
    value
        .as_str()
        .map(str::to_owned)
        .ok_or_else(|| invalid(format!("{key} must be a string")))
}

fn int(key: &str, value: &Value, min: i64, max: i64) -> Result<i64, Error> {
    match value.as_i64() {
        Some(n) if (min..=max).contains(&n) => Ok(n),
        _ => Err(invalid(format!("{key} must be an integer from {min} to {max}"))),
    }
}

fn boolean(key: &str, value: &Value) -> Result<bool, Error> {
    value.as_bool().ok_or_else(|| invalid(format!("{key} must be a boolean")))
}

/// Callers have range-checked `n` as non-negative.
fn seconds(n: i64) -> Seconds {
    Seconds(n.unsigned_abs())
}

/// Characters of group, deduplication and queue-name parts.
fn is_id_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_' || c == '-'
}

fn valid_queue_name(name: &str) -> bool {
    let stem = name.strip_suffix(".fifo").unwrap_or(name);
    let limit = if stem.len() == name.len() { 80 } else { 75 };
    (1..=limit).contains(&stem.len()) && stem.chars().all(is_id_char)
}

fn id_string(params: &Params, key: &str) -> Result<Option<String>, Error> {
    let Some(value) = params.string(key)? else {
        return Ok(None);
    };
    if (1..=128).contains(&value.len()) && value.chars().all(is_id_char) {
        Ok(Some(value))
    } else {
        Err(invalid(format!("{key} must be 1 to 128 characters of A-Z a-z 0-9 _ -")))
    }
}

fn attributes(value: &Value) -> Result<AttributeSet, Error> {
    let object = value
        .as_object()
        .ok_or_else(|| invalid("Attributes must be an object".to_owned()))?;
    let params = Params(object.clone());
    if let Some(unknown) = object.keys().find(|k| {
        !matches!(
            k.as_str(),
            "VisibilityTimeout"
                | "DelaySeconds"
                | "RetentionSeconds"
                | "Fifo"
                | "ContentBasedDeduplication"
                | "DeadLetterQueue"
                | "MaxReceiveCount"
        )
    }) {
        return Err(invalid(format!("unknown attribute {unknown}")));
    }
    Ok(AttributeSet {
        visibility_timeout: params.seconds("VisibilityTimeout", 0, 43_200)?,
        delay: params.seconds("DelaySeconds", 0, 900)?,
        retention: params.seconds("RetentionSeconds", 60, 1_209_600)?,
        fifo: params.get("Fifo").map(|v| boolean("Fifo", v)).transpose()?,
        content_based_dedup: params
            .get("ContentBasedDeduplication")
            .map(|v| boolean("ContentBasedDeduplication", v))
            .transpose()?,
        dead_letter_queue: params.string("DeadLetterQueue")?,
        max_receive_count: params
            .int("MaxReceiveCount", 1, 1000)?
            .map(|n| u32::try_from(n).expect("range-checked to 1..=1000")),
    })
}

pub fn parse(line: &[u8]) -> Result<Request, Error> {
    let malformed = |what: &str| Error::new(Code::InvalidRequest, what.to_owned());
    let text = std::str::from_utf8(line).map_err(|_| malformed("line is not valid UTF-8"))?;
    let Value::Object(members) = serde_json::from_str(text)
        .map_err(|e| Error::new(Code::InvalidRequest, format!("line is not valid JSON: {e}")))?
    else {
        return Err(malformed("line is not a JSON object"));
    };
    let params = Params(members);
    let command = params
        .0
        .get("Command")
        .and_then(Value::as_str)
        .ok_or_else(|| malformed("Command must be a string"))?;

    let name = |params: &Params| -> Result<String, Error> {
        string("QueueName", params.required("QueueName")?)
    };
    match command {
        "CreateQueue" => {
            let name = name(&params)?;
            if !valid_queue_name(&name) {
                return Err(Error::new(Code::QueueNameInvalid, format!("invalid queue name {name:?}")));
            }
            let attributes = params.get("Attributes").map(attributes).transpose()?.unwrap_or_default();
            Ok(Request::CreateQueue { name, attributes })
        }
        "SetQueueAttributes" => {
            let value = params.required("Attributes")?;
            let queue = params.required("QueueName")?;
            let name = string("QueueName", queue)?;
            Ok(Request::SetQueueAttributes { name, attributes: attributes(value)? })
        }
        "GetQueueAttributes" => Ok(Request::GetQueueAttributes { name: name(&params)? }),
        "ListQueues" => Ok(Request::ListQueues { prefix: params.string("Prefix")? }),
        "DeleteQueue" => Ok(Request::DeleteQueue { name: name(&params)? }),
        "PurgeQueue" => Ok(Request::PurgeQueue { name: name(&params)? }),
        "Tick" => {
            let value = params.required("Seconds")?;
            Ok(Request::Tick { seconds: seconds(int("Seconds", value, 0, 1_209_600)?) })
        }
        "SendMessage" => {
            params.required("QueueName")?;
            let body = params.required("Body")?;
            let name = name(&params)?;
            let body = string("Body", body)?;
            if !(1..=1024).contains(&body.len()) {
                return Err(invalid("Body must be 1 to 1024 bytes".to_owned()));
            }
            Ok(Request::SendMessage {
                name,
                body,
                delay: params.seconds("DelaySeconds", 0, 900)?,
                group_id: id_string(&params, "GroupId")?,
                dedup_id: id_string(&params, "DeduplicationId")?,
            })
        }
        "ReceiveMessage" => {
            let name = name(&params)?;
            let max_messages = params.int("MaxMessages", 1, 10)?.unwrap_or(1);
            Ok(Request::ReceiveMessage {
                name,
                max_messages: usize::try_from(max_messages).expect("range-checked to 1..=10"),
                visibility_timeout: params.seconds("VisibilityTimeout", 0, 43_200)?,
            })
        }
        "DeleteMessage" | "ChangeMessageVisibility" => {
            let queue = params.required("QueueName")?;
            let handle = params.required("ReceiptHandle")?;
            let timeout = (command == "ChangeMessageVisibility")
                .then(|| params.required("VisibilityTimeout"))
                .transpose()?;
            let name = string("QueueName", queue)?;
            let handle = string("ReceiptHandle", handle)?;
            match timeout {
                None => Ok(Request::DeleteMessage { name, handle }),
                Some(value) => Ok(Request::ChangeMessageVisibility {
                    name,
                    handle,
                    visibility_timeout: seconds(int("VisibilityTimeout", value, 0, 43_200)?),
                }),
            }
        }
        other => Err(malformed(&format!("unknown command {other:?}"))),
    }
}
