    if usable {
        Ok(Outcome::Empty {})
    } else {
        Err(Error::new(Code::ReceiptHandleExpired, "the receipt handle is not usable".to_owned()))
    }
}

fn dead_letter_of(set: &AttributeSet) -> Result<Option<DeadLetter>, Error> {
    match (&set.dead_letter_queue, set.max_receive_count) {
        (Some(queue), Some(max_receive_count)) => {
            Ok(Some(DeadLetter { queue: queue.clone(), max_receive_count }))
        }
        (None, None) => Ok(None),
        _ => Err(Error::new(
            Code::InvalidParameterValue,
            "DeadLetterQueue and MaxReceiveCount go together".to_owned(),
        )),
    }
}
