        let now = self.now;
        let queue = self.queue(name)?;
        let missing = |what: &str| Err(Error::new(Code::MissingParameter, format!("{what} is required")));
        let fifo = if queue.attributes.fifo {
            if delay.is_some() {
                return Err(unsupported("DelaySeconds on a FIFO queue"));
            }
            let Some(group) = group_id.as_deref() else {
                return missing("GroupId");
            };
            let dedup = match (&dedup_id, queue.attributes.content_based_dedup) {
                (Some(id), _) => id.as_str(),
                (None, true) => body,
                (None, false) => return missing("DeduplicationId"),
            };
            if let Some((id, sequence)) = queue.duplicate_of(now, dedup) {
                return Ok(Outcome::Sent { id, sequence: Some(sequence) });
            }
            Some(FifoSend { group, dedup_id: dedup })
        } else {
            if group_id.is_some() || dedup_id.is_some() {
                return Err(unsupported("GroupId and DeduplicationId on a standard queue"));
            }
            None
        };
        if queue.is_full() {
            return Err(Error::new(Code::LimitExceeded, "the queue holds 100000 messages".to_owned()));
        }
        self.messages_accepted += 1;
        let id = MessageId(self.messages_accepted);
        let sequence = queue.accept(now, id, body, delay, fifo);
        Ok(Outcome::Sent { id, sequence })
    }

    fn receive(
        &mut self,
        name: &str,
        max_messages: usize,
        visibility_timeout: Option<Seconds>,
    ) -> Result<Outcome, Error> {
        let now = self.now;
        let queue = self.queue(name)?;
        let timeout = visibility_timeout.unwrap_or(queue.attributes.visibility_timeout);
        let dead_letter = queue.attributes.dead_letter.as_ref().map(|d| d.queue.clone());
        let receipt = queue.receive(now, max_messages, timeout, &mut self.handles_issued_next());
        self.handles_issued += receipt.delivered.len() as u64;
        if let Some(target) = dead_letter {
            let target = self.queue(&target)?;
            for message in receipt.dead {
                target.accept_dead(now, message);
            }
        }
        Ok(Outcome::Messages { messages: receipt.delivered })
    }

    /// Checks that `text` is a handle this process has issued, then finds the queue.
    fn resolve_handle(&mut self, name: &str, text: &str) -> Result<(&mut Queue, ReceiptHandle), Error> {
        let issued = self.handles_issued;
        let queue = self.queue(name)?;
        match ReceiptHandle::parse(text) {
            Some(handle) if (1..=issued).contains(&handle.0) => Ok((queue, handle)),
            _ => Err(Error::new(Code::ReceiptHandleInvalid, format!("handle {text:?} was never issued"))),
        }
    }
}

fn unsupported(what: &str) -> Error {
    Error::new(Code::UnsupportedOperation, format!("{what} is not supported"))
}

fn require_usable(usable: bool) -> Result<Outcome, Error> {
    if usable {
        Ok(Outcome::Empty {})
    } else {
        Err(Error::new(Code::ReceiptHandleExpired, "the receipt handle is not usable".to_owned()))
    }
}

fn dead_letter_of(set: &AttributeSet) -> Result<Option<DeadLetter>, Error> {
    match (&set.dead_letter_queue, set.max_receive_count) {
        (Some(queue), Some(max_receive_count)) => {
            Ok(Some(DeadLetter { queue: queue.clone(), max_receive_count }))
        }
        (None, None) => Ok(None),
        _ => Err(Error::new(
            Code::InvalidParameterValue,
            "DeadLetterQueue and MaxReceiveCount go together".to_owned(),
        )),
    }
}
